import requests
from bs4 import BeautifulSoup

def scrape_twitter_data(username):
    """Scrapes Twitter profile information using a simplified URL extractor."""
    try:
        url = f"https://twitter.com/{username}"
        response = requests.get(url)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

        soup = BeautifulSoup(response.content, 'html.parser')
        profile_data = {
            "username": username,
            "created_at": soup.find('time', {
                'class': 'twitter-text'
            }).text.strip(),
            "profile_url": soup.find('a', {'class': 'twitter-profile-link'}).get('href')
        }
        return profile_data

    except requests.exceptions.RequestException as e:
        print(f"Social Media Error: {e}")
        return None

if __name__ == '__main__':
    # Example usage:
    user_to_scrape = "elonmusk"
    data = scrape_twitter_data(user_to_scrape)

    if data:
        print(f"User: {user_to_scrape}")
        print(f"Created At: {data['created_at']}")
        print(f"Profile URL: {data['profile_url']}")
    else:
        print("Could not retrieve basic profile information.")
